import{_ as a,C as n,c as r,o as i,a3 as t,G as o}from"./chunks/framework.Dokpd4od.js";const u=JSON.parse('{"title":"Project stages and milestones","description":"","frontmatter":{},"headers":[],"relativePath":"master/services/project/project-management/project-stages-and-milestones.md","filePath":"master/services/project/project-management/project-stages-and-milestones.md","lastUpdated":1792041590000}'),l={name:"master/services/project/project-management/project-stages-and-milestones.md"};function g(d,e,c,p,m,h){const s=n("ImagePopup");return i(),r("div",null,[e[0]||(e[0]=t('<h1 id="project-stages-and-milestones" tabindex="-1">Project stages and milestones <a class="header-anchor" href="#project-stages-and-milestones" aria-label="Permalink to &quot;Project stages and milestones&quot;">​</a></h1><p>Project stages describe the phase of a whole project. Milestones are key points inside one project, such as a sign off. Stages are shared by every project. Milestones belong to one project.</p><blockquote><p><strong>In simple words:</strong> Stages say where a project is. Milestones say which big goals are reached.</p></blockquote><div class="info custom-block"><p class="custom-block-title">Three different things</p><p>A project stage is not a task stage and not a task <strong>State</strong>. Task stages and states are explained in <a href="./../task-management/task-stages-and-states.html">Task stages and states</a>.</p></div><h2 id="project-stages" tabindex="-1">Project stages <a class="header-anchor" href="#project-stages" aria-label="Permalink to &quot;Project stages&quot;">​</a></h2><p>Needs <strong>Enable Project Stages</strong> in <a href="./../get-started/project-settings.html">Project settings</a>. Without it the stage bar is hidden on the project form.</p><p>Open <code>Project → Configurations → Project Stages</code>.</p><ol><li>Click <strong>New Project Stage</strong>. A window opens.</li><li>Type a <strong>Name</strong>, for example <strong>To Do</strong>.</li><li>Click <strong>Create</strong>.</li></ol>',8)),o(s,{src:"/images1/project/cf_project_stage_form.png",alt:"Create Project Stage window with the name Review typed in"}),e[1]||(e[1]=t("<ul><li><strong><em>Name:</em></strong> Required and unique. Up to 255 characters.</li></ul><p>Add <strong>To Do</strong>, <strong>In Progress</strong>, <strong>Done</strong> and <strong>Cancelled</strong> for the example. Drag the rows to set the order. The first stage in the list is the default for a new project.</p>",2)),o(s,{src:"/images1/project/cf_project_stages_list.png",alt:"Project Stages list with To Do, In Progress, Done and Cancelled"}),e[2]||(e[2]=t('<p>Each row has <strong>Edit</strong>, <strong>Delete</strong>, <strong>Restore</strong> and <strong>Force delete</strong>. <strong>Delete</strong> archives the stage. You can group the list by <strong>Created At</strong>.</p><h2 id="milestones" tabindex="-1">Milestones <a class="header-anchor" href="#milestones" aria-label="Permalink to &quot;Milestones&quot;">​</a></h2><p>Needs <strong>Enable Milestones</strong> in settings and <strong>Allow Milestones</strong> on the project. Open the project and click <strong>Milestones</strong> in the top links.</p><ol><li>Open <strong>Website Revamp</strong> and click <strong>Milestones</strong>.</li><li>Click <strong>Add Project Milestone</strong>. A window opens.</li><li>Fill the form and click <strong>Create</strong>.</li></ol>',4)),o(s,{src:"/images1/project/pj_milestone_form.png",alt:"Create Milestone window with Name Go Live, a Deadline and Is Completed off"}),e[3]||(e[3]=t("<ul><li><strong><em>Name:</em></strong> Required. Example: <strong>Phase 1 Complete</strong>.</li><li><strong><em>Deadline:</em></strong> The date and time to reach it.</li><li><strong><em>Is Completed:</em></strong> Required toggle. Off until the goal is reached.</li><li><strong><em>Project:</em></strong> Required. Hidden when you add the milestone inside a project.</li></ul><p>The list shows <strong>Name</strong>, <strong>Deadline</strong>, <strong>Is Completed</strong> and <strong>Completed At</strong>. Switch <strong>Is Completed</strong> in the row when the goal is done. <strong>Completed At</strong> fills automatically.</p>",2)),o(s,{src:"/images1/project/pj_milestones_list.png",alt:"Milestones list of Website Revamp with Phase 1 Complete and Go Live"}),e[4]||(e[4]=t('<p>You can also reach all milestones at <code>Project → Configurations → Milestones</code>. Filter by <strong>Is Completed</strong>, <strong>Project</strong> or <strong>Creator</strong>.</p><h3 id="completed-count" tabindex="-1">Completed count <a class="header-anchor" href="#completed-count" aria-label="Permalink to &quot;Completed count&quot;">​</a></h3><p>The project card shows milestones as completed over total. With <strong>Phase 1 Complete</strong> done and <strong>Go Live</strong> open, it reads 1/2. The <strong>View</strong> page shows the same under <strong>Milestones Progress</strong>.</p><h3 id="use-on-tasks" tabindex="-1">Use on tasks <a class="header-anchor" href="#use-on-tasks" aria-label="Permalink to &quot;Use on tasks&quot;">​</a></h3><p>When a project allows milestones, the task form has a <strong>Milestone</strong> field. Link a task to a milestone there. See <a href="./../task-management/create-task.html">Create a task</a>.</p><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><ul><li><strong>Edit:</strong> changes a stage or a milestone.</li><li><strong>Delete:</strong> archives a stage. Restore it from the list filter.</li><li><strong>Force delete:</strong> removes a stage for good.</li><li>A milestone is <strong>Completed</strong> when <strong>Is Completed</strong> is on.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./create-project.html">Create a project</a></li><li><a href="./../get-started/project-settings.html">Project settings</a></li><li><a href="./../task-management/task-stages-and-states.html">Task stages and states</a></li><li><a href="./">Project management</a></li></ul>',9))])}const j=a(l,[["render",g]]);export{u as __pageData,j as default};
